// Contrato con Entry. v2 no necesita estado de slots: la continuidad la lleva la memoria
// del agente, así que flujo_activo y los pending_*/slot_* van a null y Entry los limpia.
// `intent` NO puede ser null: Entry lo usa para decidir si el saludo genérico es redundante
// detrás del aviso de privacidad, y aquí no hay saludo enlatado.
const out = $json ?? {};
const reply = (out.output ?? '').toString().trim();

// En webchat el teléfono lo teclea el cliente y solo lo conocen las tools. Si no lo
// recogemos aquí, el agente tiene que acordarse de pasarlo en CADA llamada posterior --
// y no lo hace: "lista mis citas" volvía a pedirlo a mitad de conversación. Entry lo
// guarda en state.contact_phone y lo reinyecta, igual que hace WhatsApp con el del canal.
let contact_phone = null;
for (const t of ['mis_citas', 'reservar_cita', 'cancelar_cita', 'reprogramar_cita', 'anotar_tarea']) {
  try {
    const r = $(t).first().json;
    if (r && r.telefono_usado) { contact_phone = r.telefono_usado; break; }
  } catch (e) { /* esa tool no corrió en este turno */ }
}

if (!reply) {
  console.log('Core v2: el agente no devolvió texto. ' + JSON.stringify(out).slice(0, 300));
}
return [{ json: {
  ok: true,
  intent: 'v2',
  reply_to_user: reply || 'Perdona, se me ha cruzado un cable. ¿Me lo repites?',
  needs_user_reply: true,
  flujo_activo: null,
  contact_id: null,
  contact_phone,
  result: null,
} }];
